#!/usr/bin/env node
/**
 * Write public/mobile-hub.json with this Mac's LAN hub URL.
 * The iOS shell cannot use 127.0.0.1 to reach the dev server.
 * Gitignored. Regenerated by the mobile static build.
 */
import fs from "node:fs"
import os from "node:os"
import path from "node:path"
import { fileURLToPath } from "node:url"

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const port = Number(process.env.PORT) || 3000

function lanAddress() {
  const nets = os.networkInterfaces()
  for (const entries of Object.values(nets)) {
    for (const entry of entries || []) {
      if (entry.family === "IPv4" && !entry.internal) return entry.address
    }
  }
  return null
}

const host = lanAddress()
const file = path.join(root, "public", "mobile-hub.json")
if (!host) {
  console.warn("[mobile-hub-hint] no LAN address — leaving the native shell on loopback")
  process.exit(0)
}
fs.mkdirSync(path.dirname(file), { recursive: true })
fs.writeFileSync(file, JSON.stringify({ url: `http://${host}:${port}` }) + "\n")
console.log(`[mobile-hub-hint] ${file} → http://${host}:${port}`)
